t.script:
(function(){function ev_isXO(msg){msg=msg||"";return msg.indexOf("cross-origin frame")>-1||msg.indexOf("named property 'href'")>-1||msg.indexOf("Blocked a frame")>-1;}
            window.addEventListener("error",function(e){if(ev_isXO(e&&e.message)){if(e.stopImmediatePropagation){e.stopImmediatePropagation();}if(e.preventDefault){e.preventDefault();}return false;}},true);
            window.addEventListener("unhandledrejection",function(e){var r=e&&e.reason;var m=(r&&r.message)?r.message:(""+r);if(ev_isXO(m)){if(e.stopImmediatePropagation){e.stopImmediatePropagation();}if(e.preventDefault){e.preventDefault();}return false;}},true);})();

(function(){try{if(sessionStorage.getItem("evSplashSeen")){document.documentElement.classList.add("ev-noSplash");}else{sessionStorage.setItem("evSplashSeen","1");}}catch(e){}
            /* klik na jazyk bránu okamžitě schová (než se stránka přenačte) a nastaví guard */
            document.addEventListener("click",function(e){var o=e.target.closest&&e.target.closest(".ev-langgate-opt");if(!o){return;}try{sessionStorage.setItem("evSplashSeen","1");}catch(_){}document.documentElement.classList.add("ev-noSplash");},true);})();

/* potlačí neškodnou Odoo chybu SecurityError při čtení cross-origin iframu (Google Analytics / Maps apod.) */
window.addEventListener('error', function (e) {
    var m = (e && e.message) ? e.message : '';
    if (m.indexOf('cross-origin frame') > -1 || m.indexOf("named property 'href'") > -1) {
        if (e.stopImmediatePropagation) { e.stopImmediatePropagation(); }
        if (e.preventDefault) { e.preventDefault(); }
        return false;
    }
}, true);

document.addEventListener('click', function(e) {
    var link = e.target.closest('details a');
    if (!link) return;
    var d = link.closest('details');
    if (d) d.open = false;
});

/* ===== Coach-mark: bublina u 24/7 — automaticky jednou za návštěvu + na klik na červené odkazy vždy ===== */
(function () {
    var coach = document.getElementById('ev-coach');
    if (!coach) { return; }
    function open() {
        coach.classList.add('ev-coach-on');
        document.body.classList.add('ev-coach-active');
    }
    function close() {
        coach.classList.remove('ev-coach-on');
        document.body.classList.remove('ev-coach-active');
    }
    coach.addEventListener('click', function (e) {
        /* klik do ztmavené plochy nebo na tlačítko Rozumím zavře; klik do bubliny (text) ne */
        if (e.target === coach || e.target.closest('.ev-coach-btn')) { close(); }
    });
    /* automaticky po otevření webu — jen jednou za návštěvu a až když už není jazyková brána */
    var autoOpen = document.documentElement.classList.contains('ev-noSplash');
    try { if (sessionStorage.getItem('evCoachSeen')) { autoOpen = false; } } catch (e) {}
    if (autoOpen) {
        open();
        try { sessionStorage.setItem('evCoachSeen', '1'); } catch (e) {}
    }
    /* ruční spouštěče — červená pohotovostní linka v heru, v poznámce hodin i plovoucí kolečko 24/7; otevře vždy */
    var triggers = document.querySelectorAll('.ev-cd-emergency, .ev-hours-emergency, .ev-fab247');
    for (var i = 0; i < triggers.length; i++) {
        triggers[i].style.cursor = 'pointer';
        triggers[i].addEventListener('click', function (e) { e.preventDefault(); open(); });
    }
})();


/* ===== Horní lišta: schovat při scrollu dolů, ukázat při scrollu nahoru ===== */
(function () {
    var ua = navigator.userAgent || '';
    /* v in-app webview (IG/FB) vypnuto — měnící se transform na fixed liště tam bliká */
    if (/Instagram|FBAN|FBAV|FB_IAB|Messenger|MicroMessenger|Snapchat|Pinterest/i.test(ua)) { return; }
    var nav = document.querySelector('.ev-topbar');
    if (!nav) { return; }
    var lastY = window.pageYOffset || 0;
    var ticking = false;
    function closeMenus() {
        var open = nav.querySelectorAll('details[open]');
        for (var i = 0; i < open.length; i++) { open[i].open = false; }
    }
    function navScroll() {
        var y = window.pageYOffset || 0;
        if (y > lastY + 4) {
            if (y > 90) {
                nav.classList.add('ev-nav-hidden');
                closeMenus();
            }
            lastY = y;
        } else if (lastY - 4 > y) {
            nav.classList.remove('ev-nav-hidden');
            lastY = y;
        }
        ticking = false;
    }
    window.addEventListener('scroll', function () {
        if (ticking === false) { ticking = true; window.requestAnimationFrame(navScroll); }
    }, { passive: true });
})();
